			...dataRenderLines,
			],
		),
		'	const html = marklessSsrRendered.html;',
		'	const marklessSsrComposition = marklessSsrComposeView(marklessSsrRendered.structure, payloadView, marklessSsrChildren, marklessSsrAsyncSnapshots, marklessSsrIdPrefix);',
