import { state } from '@markless/core';

export function App() @{
	let kind = state('a');

	<section>
		@switch (kind) {
			@case 'a': { <p>A</p> }
			@case 'b': { <p>B</p> }
			@default: { <p>D</p> }
		}
	</section>
}
`,
